import { router, usePage } from "@inertiajs/react";
import { useCallback, useState } from "react";
const usePageFilter = ({ handleClose, routeName, } = {}) => {
    const { props } = usePage();
    const urlFilters = props.filters || {};
    const [filters, setFilters] = useState(urlFilters);
    const [drawerOpen, setDrawerOpen] = useState(false);
    // Open filter drawer
    const openFilterDrawer = useCallback(() => {
        setDrawerOpen(true);
    }, []);
    // Close filter drawer
    const closeFilterDrawer = useCallback(() => {
        setDrawerOpen(false);
        handleClose?.();
    }, [handleClose]);
    // Handle quick filter changes (for the filter bar)
    const handleQuickFilter = useCallback((key, value) => {
        setFilters((prev) => {
            const updated = { ...prev };
            if (value === "" ||
                value === "all" ||
                value === null ||
                value === undefined) {
                delete updated[key];
            }
            else {
                if (typeof value === "string" ||
                    typeof value === "number") {
                    updated[key] = value;
                }
            }
            return updated;
        });
    }, []);
    // Remove a specific filter
    const removeFilter = useCallback((key) => {
        setFilters((prev) => {
            const updated = { ...prev };
            delete updated[key];
            return updated;
        });
    }, []);
    // Reset filters
    const handleResetQuickFilters = useCallback(() => {
        setFilters({});
    }, []);
    // Clear all filters and navigate
    const clearAllFilters = useCallback(() => {
        const currentRoute = routeName || window.location.pathname.split("/").pop() || "index";
        const routeNameToUse = currentRoute.includes(".")
            ? currentRoute
            : `${currentRoute}.index`;
        router.get(route(routeNameToUse), {}, {
            preserveState: true,
            preserveScroll: true,
        });
        setFilters({});
        handleClose?.();
    }, [routeName, handleClose]);
    // Handle filter form submission
    const handleFilterSubmit = useCallback((values) => {
        const newFilters = { ...filters, ...values };
        // Remove empty values
        Object.keys(newFilters).forEach((key) => {
            const value = newFilters[key];
            if (value === null ||
                value === undefined ||
                value === "" ||
                value === "all" ||
                (Array.isArray(value) && value.length === 0)) {
                delete newFilters[key];
            }
        });
        const currentRoute = routeName ||
            window.location.pathname.split("/").pop() ||
            "index";
        const routeNameToUse = currentRoute.includes(".")
            ? currentRoute
            : `${currentRoute}.index`;
        router.get(route(routeNameToUse), newFilters, {
            preserveState: true,
            preserveScroll: true,
        });
        setFilters(newFilters);
        handleClose?.();
    }, [filters, routeName, handleClose]);
    // Reset filters
    const handleResetFilters = useCallback(() => {
        const currentRoute = routeName || window.location.pathname.split("/").pop() || "index";
        const routeNameToUse = currentRoute.includes(".")
            ? currentRoute
            : `${currentRoute}.index`;
        router.get(route(routeNameToUse), {}, {
            preserveState: true,
            preserveScroll: true,
        });
        setFilters({});
        handleClose?.();
    }, [routeName, handleClose]);
    return {
        filters,
        drawerOpen,
        openFilterDrawer,
        closeFilterDrawer,
        handleQuickFilter,
        removeFilter,
        handleResetQuickFilters,
        handleResetFilters,
        handleFilterSubmit,
        clearAllFilters,
    };
};
export default usePageFilter;
