// Type guards for response checking
export const isSuccessResponse = (response) => {
    return response.status === "success" && !("action" in response);
};
export const isErrorResponse = (response) => {
    return (response.status === "fail" &&
        "message" in response &&
        !("errors" in response));
};
export const isFormErrorResponse = (response) => {
    return (Boolean(response.status === "fail" && "errors" in response) ||
        Boolean(response?.message && "errors" in response));
};
export const isRedirectResponse = (response) => {
    return (response.status === "success" &&
        "action" in response &&
        response.action === "redirect");
};
